const domain=url=>{try{return new URL(url).hostname.replace(/^www\./,'');}catch{return 'Your notebook';}};
const dateLabel=d=>{const days=Math.floor((Date.now()-new Date(d))/86400000); return days<1?'Today':days===1?'Yesterday':new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric'});};
const previewText=s=>String(s||'').replace(/^#+\s*/gm,'').replace(/\*\*|__|`|\[.\]\s*/g,'').slice(0,180);
function toast(message,error=false){const el=document.createElement('div');el.className=`toast ${error?'error':''}`;el.innerHTML=icon(error?'help':'check')+`<span>${esc(message)}</span>`;$('#toast-root').append(el);setTimeout(()=>el.remove(),4500);}
const run=async fn=>{try{return await fn();}catch(e){console.error(e);toast(e.message||'Something went wrong. Your library is still here.',true);}};
async function ensureOrigin(origin){if(isExtension&&!await chrome.permissions.request({origins:[origin]}))throw new Error('Access was not granted. You can try again when you’re ready.');}
async function chromeRequest(type,extra={}){if(!isExtension)throw new Error('Load Still as a Chrome extension to use browser capture.');const response=await chrome.runtime.sendMessage({type,...extra});if(!response?.ok)throw new Error(response?.error||'Chrome could not complete that action.');return response.result;}
function applyTheme(){const value=library.settings.theme||'light';document.documentElement.dataset.theme=value==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):value;document.body.classList.toggle('compact',!!library.settings.compact);}
function navRow(id,label,ico,count,extra=''){return `<button class="nav-item ${currentView===id?'active':''}" data-action="navigate" data-view="${esc(id)}" ${currentView===id?'aria-current="page"':''} ${extra}>${icon(ico)}<span>${esc(label)}</span>${count!==undefined?`<span class="nav-count">${count}</span>`:''}</button>`;}
function getCurrentSpaceContext(){return buildSpaceContext(library,currentView.startsWith('collection:')?'space:'+currentView.slice(11):currentView==='inbox'?'inbox':currentView==='map'?mapScopeKey:null);}
function currentLayout(){const space=getCurrentSpaceContext(),side=params.get('view')==='sidepanel';if(space?.kind==='collection')return collection(space.id)?.[side?'sidebarLayout':'layout']||(side?'list':'grid');return library.settings[space?.kind==='inbox'?(side?'inboxSideLayout':'inboxLayout'):(side?'sideLayout':'layout')]||(side?'list':'grid');}
function orderedCollections(){const result=[],seen=new Set(),all=library.collections.filter(c=>!c.deletedAt);const pinnedFirst=rows=>rows.sort((a,b)=>Number(!!b.pinned)-Number(!!a.pinned));function walk(parentId='',depth=0){for(const c of pinnedFirst(all.filter(c=>(c.parentId||'')===parentId))){if(seen.has(c.id))continue;seen.add(c.id);result.push({...c,depth});walk(c.id,Math.min(depth+1,5));}}walk();for(const c of pinnedFirst(all.filter(c=>!seen.has(c.id))))result.push({...c,depth:0});return result;}
async function openSpace(key){const space=buildSpaceContext(library,key);if(!space)throw new Error('This space is no longer available.');if($('#edit-form')?.dataset.dirty==='true')await saveOpenEdits();if(!closeModal())return;currentView=space.kind==='inbox'?'inbox':'collection:'+space.id;search='';typeFilter='all';activeTag='';selected.clear();mobileNav=false;render();}
async function openFullWorkspace(){if($('#edit-form')?.dataset.dirty==='true')await saveOpenEdits();const url=new URL(isExtension?chrome.runtime.getURL('index.html'):new URL('index.html',location.href));url.searchParams.set('libraryView',currentView);if(mapScopeKey)url.searchParams.set('mapSpace',mapScopeKey);if(search)url.searchParams.set('q',search);if(typeFilter!=='all')url.searchParams.set('type',typeFilter);if(activeTag)url.searchParams.set('tag',activeTag);const editor=getEditorContext();if(editor?.id)url.searchParams.set('item',editor.id);if(isExtension)await chrome.tabs.create({url:url.href});else window.open(url.href,'_blank','noopener');}
