function renderNotebook(){const note=activeItems().find(i=>i.type==='note'&&i.pinned)||activeItems().find(i=>i.type==='note');const recents=activeItems().filter(i=>i.type==='note'&&i.id!==note?.id).slice(0,3);return `<div class="notebook-heading"><span>${icon('note')} YOUR NOTEBOOK</span>${button('toggle-notebook','Close notebook','close')}</div><div class="notebook-intro"><span class="handwritten">a thought, before it goes.</span><h2>A little room<br>for your ideas.</h2><p>Your finds are only the beginning.</p></div>${button('new-note','Write a note','plus','button notebook-new')}<div class="notebook-sheet">${note?`<div class="sheet-label">${icon('pin')} PINNED THOUGHT</div><button class="sheet-title" data-action="open-item" data-id="${esc(note.id)}">${esc(note.title)}</button><div class="sheet-content">${markdown(note.content,false,true)}</div><div class="sheet-bottom"><span>${note.relatedIds.length} connected items</span>${button('open-item','Continue writing','edit','icon-button',`data-id="${esc(note.id)}"`)}</div>`:'<div class="sheet-label">A FRESH PAGE</div><p>That idea you almost forgot?<br>There’s room for it here.</p>'}</div><div class="recent-notes"><span class="eyebrow">RECENT THOUGHTS</span>${recents.map(n=>`<button data-action="open-item" data-id="${esc(n.id)}">${icon('note')}<span><strong>${esc(n.title)}</strong><small>${dateLabel(n.updatedAt)}</small></span>${icon('chevron')}</button>`).join('')}</div><div class="notebook-footer"><div class="tiny-flower">✳</div><p>Collect with curiosity.<br>Create with a little clarity.</p></div>`;}

function releaseEditor(){
 aiUI?.detachFromEditor();
 if(blockEditor){const area=$('#note-editor');if(area&&blockEditor.root.hidden!==true)area.value=blockEditor.getMarkdown();blockEditor.destroy();blockEditor=null;}
 editorSelectionRange=null;lastEditorSelection='';
}
function openModal(html,cls=''){
 if($('#edit-form,#collection-form')?.dataset.dirty==='true'&&!confirm('Leave without saving your latest changes?'))return null;
 modalReturnFocus=document.activeElement;releaseEditor();
 $('#active-dialog')?.close();overlay.innerHTML=`<dialog class="glass-dialog ${cls}" id="active-dialog">${html}</dialog>`;
 const dialog=$('#active-dialog');dialog.setAttribute('aria-label',$('h2',dialog)?.textContent||$('.detail-title',dialog)?.value||'Still dialog');dialog.showModal();return dialog;
}
function closeModal(){if($('#edit-form,#collection-form')?.dataset.dirty==='true'&&!confirm('Close without saving your latest changes?'))return false;releaseEditor();const d=$('#active-dialog');if(d)d.close();overlay.innerHTML='';modalReturnFocus?.isConnected&&modalReturnFocus?.focus?.();return true;}
function getEditorContext(){
 const form=$('#edit-form'),area=$('#note-editor');if(!form||!area)return null;
 const draft=blockEditor&&!blockEditor.root.hidden?blockEditor.getMarkdown():area.value;
 const selection=!area.hidden?area.value.slice(area.selectionStart,area.selectionEnd):blockEditor?.getSelection()||lastEditorSelection;
 return {id:form.dataset.id,title:String(new FormData(form).get('title')||''),draft,selection,revision:form.dataset.revision||''};
}
function setEditorMode(mode){
 const area=$('#note-editor'),preview=$('.editor-preview');if(!area||!preview)return;
 if(blockEditor&&!blockEditor.root.hidden)area.value=blockEditor.getMarkdown();
 if(blockEditor)blockEditor.root.hidden=mode!=='blocks';
 area.hidden=mode!=='markdown';preview.hidden=mode!=='preview';
 if(mode==='blocks')blockEditor?.show();
 if(mode==='preview')preview.innerHTML=markdown(area.value,true);
 if(mode==='markdown')area.focus();
 for(const control of document.querySelectorAll('[data-action="editor-mode"]')){const active=control.dataset.mode===mode;control.classList.toggle('active',active);control.setAttribute('aria-pressed',String(active));}
 const label=$('.editor-format');if(label)label.textContent=mode==='blocks'?'Type / for blocks':mode==='markdown'?'Markdown source':'Reading preview';
}
function mountNoteEditor(){
 const area=$('#note-editor');if(!area)return;
 blockEditor=mountBlockEditor(area,{onChange:()=>{const form=$('#edit-form');if(form)form.dataset.dirty='true';},onAskAi:({selection,draft})=>aiUI?.open({intent:'chat',scope:'selected',itemId:$('#edit-form')?.dataset.id,selection,draft})});
 const shortcuts=document.createElement('div');shortcuts.className='editor-ai-shortcuts';shortcuts.setAttribute('aria-label','AI writing actions');
 shortcuts.innerHTML=`<span>${icon('sparkles')} A little help with your writing</span>${[['summarize','Summarize'],['rewrite','Improve'],['tasks','Checklist'],['continue','Continue']].map(([intent,label])=>`<button type="button" data-action="ask-ai" data-intent="${intent}">${label}</button>`).join('')}`;
 blockEditor.root.querySelector('.block-editor-foot').after(shortcuts);
 setEditorMode('blocks');
}
async function applyAiToDraft({text,mode='append',targetId,baseDraft}){
 const form=$('#edit-form'),area=$('#note-editor');
 if(!form||!area||form.dataset.id!==targetId)throw new Error('Reopen the note this response was written for before adding it to a draft.');
 if(typeof text!=='string'||!text.trim())throw new Error('There is no AI text to add yet.');
 const current=getEditorContext().draft;
 if(mode==='replace'&&typeof baseDraft==='string'&&current!==baseDraft&&!confirm('Your draft changed after this AI request started. Replace the current draft with this response? The replacement will remain unsaved until you choose Save changes.'))throw new Error('Replacement cancelled. Your current draft is still here.');
 let next;
 if(mode==='replace')next=text;
 else if(mode==='append')next=current+(current.trim()?'\n\n':'')+text;
 else if(mode==='insert'){
  if(!area.hidden){const start=area.selectionStart,end=area.selectionEnd;next=current.slice(0,start)+text+current.slice(end);}
  else if(blockEditor&&editorSelectionRange?.commonAncestorContainer.isConnected&&blockEditor.root.contains(editorSelectionRange.commonAncestorContainer)){
   const range=editorSelectionRange.cloneRange(),node=document.createTextNode(text);range.deleteContents();range.insertNode(node);range.setStartAfter(node);range.collapse(true);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);const editable=node.parentElement.closest('[data-block-edit]');editable?.dispatchEvent(new Event('input',{bubbles:true}));next=blockEditor.getMarkdown();
  }else next=current+(current.trim()?'\n\n':'')+text;
 }else throw new Error('Choose replace, append, or insert.');
 if(blockEditor)blockEditor.setMarkdown(next);area.value=next;area.dispatchEvent(new Event('input',{bubbles:true}));form.dataset.dirty='true';setEditorMode('blocks');aiUI?.refreshContext?.();
 return {applied:true,saved:false};
}
