const localDateTime=value=>{const d=new Date(value);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
function editCollection(id){
 const c=collection(id),excluded=new Set(getDescendantCollectionIds(library,id));
 const layoutOptions=value=>['grid','list','masonry'].map(name=>`<option value="${name}" ${value===name?'selected':''}>${name[0].toUpperCase()+name.slice(1)}</option>`).join('');
 openModal(`${modalHeader(c?'Make this space your own.':'Make a little space.','A home for related sources, files and thoughts.')}<form id="collection-form" data-id="${esc(id||'')}" data-revision="${esc(c?.updatedAt||'')}" data-dirty="false"><label>Name<input name="name" required maxlength="500" autofocus value="${esc(c?.name||'')}" placeholder="What belongs together?"></label><label>Description<textarea name="description" rows="4" maxlength="12000" placeholder="What is this space for? Add context for you and your AI.">${esc(c?.description||'')}</textarea></label><label>Cover URL<input name="cover" inputmode="url" value="${esc(c?.cover||'')}" placeholder="https://example.com/a-little-inspiration.jpg"></label><div class="form-row"><label>Color<input type="color" name="color" value="${/^#[\da-f]{6}$/i.test(c?.color||'')?c.color:'#9085c2'}"></label><label>Icon<select name="icon">${['folder','sparkles','book','layers','sun','heart','note','globe','bolt'].map(n=>`<option value="${n}" ${c?.icon===n?'selected':''}>${n[0].toUpperCase()+n.slice(1)}</option>`).join('')}</select></label></div><label>Parent collection<select name="parentId"><option value="">Top level</option>${orderedCollections().filter(x=>!excluded.has(x.id)).map(x=>`<option value="${esc(x.id)}" ${c?.parentId===x.id?'selected':''}>${esc('— '.repeat(x.depth)+x.name)}</option>`).join('')}</select></label><div class="form-row"><label>Full-tab layout<select name="layout">${layoutOptions(c?.layout||'grid')}</select></label><label>Sidebar layout<select name="sidebarLayout">${layoutOptions(c?.sidebarLayout||'list')}</select></label></div><label class="toggle-label"><span>Pin this space in navigation</span><input type="checkbox" name="pinned" ${c?.pinned?'checked':''}></label><p class="form-error" role="alert"></p><div class="dialog-footer">${c?button('delete-collection','Delete space','trash','text-button',`data-id="${esc(id)}"`):'<span></span>'}<button type="submit" class="button primary">${icon('check')}${c?'Save space':'Create space'}</button></div></form>`);
}
function itemMenu(id){const i=getItem(id);if(!i)return;openModal(`${modalHeader(i.title)}<div class="action-menu">${button('open-item','Open & edit',i.type,'menu-action',`data-id="${esc(id)}"`)}${i.url?`<a class="menu-action" href="${esc(i.url)}" target="_blank" rel="noopener noreferrer">${icon('external')}Open original</a>`:''}${button('new-linked-note','Write a connected note','note','menu-action',`data-id="${esc(id)}"`)}${button('move-item','Move to a collection','folder','menu-action',`data-id="${esc(id)}"`)}${button('pin',i.pinned?'Unpin from notebook':'Pin to notebook','pin','menu-action',`data-id="${esc(id)}"`)}${button('send-raindrop','Send to Raindrop','upload','menu-action',`data-id="${esc(id)}"`)}${i.deletedAt?button('restore','Restore item','restore','menu-action',`data-id="${esc(id)}"`)+button('permanent-delete','Delete permanently','trash','menu-action danger',`data-id="${esc(id)}"`):button('archive',i.archived?'Move out of archive':'Archive item','archive','menu-action',`data-id="${esc(id)}"`)+button('trash','Move to trash','trash','menu-action danger',`data-id="${esc(id)}"`)}</div>`,'small-dialog');}
function chooseCollection(ids){openModal(`${modalHeader('Find a home for it.')}<form id="move-form" data-ids="${esc(JSON.stringify(ids))}"><label>Collection<select name="collectionId">${collectionOptions(getItem(ids[0])?.collectionId)}</select></label><div class="dialog-footer"><span>${ids.length} ${ids.length===1?'item':'items'}</span><button class="button primary" type="submit">Move here ${icon('arrow')}</button></div></form>`,'small-dialog');}
async function showIntegrations(){integrationState=await integrations.getIntegrationSettings();const setup=await integrations.getMcpSetup();openModal(`${modalHeader('A more connected space.','Your saved knowledge, wherever your next idea happens.')}<div class="integration-intro">${icon('plug')} One library. A few more possibilities.</div><div class="integration-grid"><div class="integration-card featured"><div class="integration-logo claude-logo">✳</div><h3>Claude</h3><p>Search your library, read your notes, and save a thought from your conversation.</p><span class="integration-badge">Local MCP · setup required</span><button class="text-button" data-action="show-mcp" data-client="claude">Set up Claude ${icon('arrow')}</button></div><div class="integration-card featured"><div class="integration-logo codex-logo">${icon('command')}</div><h3>Codex</h3><p>Bring your sources, bookmarks, and project notes into your coding workspace.</p><span class="integration-badge">Local MCP · setup required</span><button class="text-button" data-action="show-mcp" data-client="codex">Set up Codex ${icon('arrow')}</button></div></div><section class="integration-section"><div class="section-label"><h3><span class="raindrop-logo">◒</span> Raindrop.io</h3><span class="integration-badge">${integrationState.raindropConnectedAt?'Verified on '+dateLabel(integrationState.raindropConnectedAt):integrationState.raindropConfigured?'Token saved · verify connection':'Not connected'}</span></div><p>Bring your collections, bookmarks, highlights, and notes into Still. Send individual links back whenever you like.</p><form id="raindrop-form"><label>Personal API token<input type="password" name="token" placeholder="Paste your Raindrop test token" autocomplete="off"></label><div class="integration-buttons"><button type="submit" class="button secondary">Save token</button>${button('test-raindrop','Test connection','check','button secondary')}${button('import-raindrop','Import library','download','button primary')}${button('disconnect-raindrop','Disconnect','close','icon-button')}</div></form><a href="https://developer.raindrop.io/v1/authentication/token" target="_blank" rel="noopener noreferrer" class="text-link">How to get a personal token ${icon('external')}</a></section><section class="integration-section"><div class="section-label"><h3>${icon('plug')} Local MCP bridge</h3><span class="integration-badge" id="bridge-status">${stopSync?'Sync running':'Disconnected'}</span></div><p>The optional bridge shares your library with Claude and Codex on this computer. It runs only when you start it.</p><form id="bridge-form"><div class="form-row"><label>Bridge address<input name="url" type="url" value="${esc(integrationState.bridgeUrl||'http://127.0.0.1:43123')}"></label><label>Pairing token<input name="token" type="password" placeholder="From the local bridge config file" autocomplete="off"></label></div><div class="integration-buttons"><button type="submit" class="button primary">${icon('plug')} Pair & start sync</button>${button('stop-sync','Stop sync','close','button secondary')}</div></form><p class="hint">Keep a Still view open for live sync. The bridge never installs or configures your AI clients.</p></section><section class="integration-section"><h3>Works with your workflow.</h3><p>Use the official Raindrop integrations for connected accounts, or move your data with portable backups.</p><div class="integration-links">${(integrations.INTEGRATION_CATALOG||[]).map(c=>`<a href="${esc(c.url||c.href||'https://help.raindrop.io/integrations')}" target="_blank" rel="noopener noreferrer">${icon(c.category==='AI'?'sparkles':'external')}<span>${esc(c.name||c.title)}</span>${icon('arrow')}</a>`).join('')}</div></section><p class="form-error" role="alert"></p><div class="dialog-footer"><span>${icon('check')} Tokens stay on this device.</span>${button('close-modal','All set','check','button secondary')}</div>`,'wide-dialog');}
async function showMcp(client){const setup=await integrations.getMcpSetup();openModal(`${modalHeader(`Bring Still to ${client==='claude'?'Claude':'Codex'}.`,'An optional bridge. The same notes and good finds.')}<div class="setup-steps"><span class="step-number">1</span><div><h3>Start the local bridge</h3><p>From the Still project folder, run:</p><pre><code>node bridge/server.mjs</code></pre><p class="hint">The terminal shows the local address and configuration file path. Copy the token from bridge/.local/config.json. Keep that terminal running.</p></div><span class="step-number">2</span><div><h3>Pair your library</h3><p>Open Integrations → Local MCP bridge. Enter the address and token, then choose Pair & start sync.</p></div><span class="step-number">3</span><div><h3>Connect your assistant</h3><p>${client==='claude'?'Add this MCP server to Claude Desktop’s developer configuration.':'Add this server to your Codex MCP configuration.'}</p><pre><code>${esc(typeof setup[client]==='string'?setup[client]:JSON.stringify(setup[client]||setup,null,2))}</code></pre><p class="hint">See docs/integrations.md for exact local paths, commands, and supported tools.</p></div></div><div class="dialog-footer"><span>Local setup · no account needed</span>${button('integrations','Back to integrations','back','button secondary')}</div>`,'wide-dialog');}
function showSettings(){openModal(`${modalHeader('Make yourself at home.','Small preferences. Your space.')}<form id="settings-form"><section class="settings-section"><h3>${icon('sun')} The way it feels</h3><label>Appearance<select name="theme">${['light','dark','system'].map(t=>`<option value="${t}" ${library.settings.theme===t?'selected':''}>${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select></label><label class="toggle-label"><span>Keep things a little more compact</span><input name="compact" type="checkbox" ${library.settings.compact?'checked':''}></label><label class="toggle-label"><span>Show your notebook alongside the library</span><input name="showNotebook" type="checkbox" ${notebook?'checked':''}></label></section><section class="settings-section"><h3>${icon('download')} Take your library with you</h3><p>Full backups include original files and notes. HTML bookmarks work with most browsers and bookmark managers.</p><div class="settings-buttons">${button('export-json','Full backup','download','button secondary')}${button('export-html','Bookmark HTML','external','button secondary')}${button('export-markdown','Notes as Markdown','note','button secondary')}${button('import','Import a library','upload','button secondary')}${button('import-browser','Import Chrome bookmarks','bookmark','button secondary')}</div><p class="hint">Imports merge with your library. Existing items are kept. Credentials are excluded from backups.</p></section><section class="settings-section"><h3>${icon('command')} A few shortcuts</h3><div class="shortcut-row"><span>Find anything</span><kbd>Ctrl / ⌘ K</kbd></div><div class="shortcut-row"><span>A new note</span><kbd>N</kbd></div><div class="shortcut-row"><span>Save something</span><kbd>A</kbd></div><div class="shortcut-row"><span>Close a dialog</span><kbd>Esc</kbd></div></section><p class="form-error" role="alert"></p><div class="dialog-footer"><span>Still · 0.1.0 · Local first</span><button class="button primary" type="submit">Save preferences ${icon('check')}</button></div></form>`);}
function showHelp(){openModal(`${modalHeader('A quieter corner of the internet.','A few ways to make this space your own.')}<div class="help-grid">${[['bookmark','Keep a good find','Save a link, upload a file, or use the extension’s right-click menu on a page, link, image, or selected text.'],['link','Let your ideas connect','Open any item to add a note, keep highlights, and link related notes or sources.'],['folder','Give things a little order','Create collections, drag items into them, and use tags to connect things across collections.'],['plug','Bring your knowledge along','Pair the optional local MCP bridge with Claude or Codex. Import from Raindrop with your own API token.']].map(([ico,title,body])=>`<div>${icon(ico)}<h3>${title}</h3><p>${body}</p></div>`).join('')}</div><div class="help-links"><a href="https://help.raindrop.io/" target="_blank" rel="noopener noreferrer">Raindrop documentation ${icon('external')}</a><button data-action="references" class="text-button">Explore all ${REFERENCE_ASSETS.length} supplied references ${icon('arrow')}</button></div><div class="dialog-footer"><span>${icon('heart')} Make room for something good.</span>${button('close-modal','Got it','check','button primary')}</div>`,'wide-dialog');}
function showReferences(){openModal(`${modalHeader('The reference room.',`All ${REFERENCE_ASSETS.length} supplied images, kept intact and considered in this workspace.`)}<p class="references-description">Library layouts, linked notes, capture, collections, highlights, files, and connected tools. These are the original reference images you supplied.</p><div class="reference-grid">${REFERENCE_ASSETS.map(a=>`<figure><a href="${esc(a.path)}" target="_blank" rel="noopener noreferrer"><img src="${esc(a.path)}" alt="${esc(a.description)}" loading="lazy"></a><figcaption><strong>${esc(a.description)}</strong><small>${esc(a.name)}</small></figcaption></figure>`).join('')}</div><div class="dialog-footer"><a class="text-link" href="https://help.raindrop.io/" target="_blank" rel="noopener noreferrer">Explore the documentation ${icon('external')}</a>${button('help','Back to help','back','button secondary')}</div>`,'reference-dialog');}
function showImport(){openModal(`${modalHeader('Bring your good finds along.','Your existing library stays with you. Imported items merge by their IDs.')}<form id="import-form"><div class="upload-drop"><div>${icon('upload')}</div><h3>A little room for what you already have.</h3><p>Choose a full Still JSON backup, browser bookmarks HTML, or a CSV with URL and title columns.</p><input type="file" name="libraryFile" accept=".json,.html,.htm,.csv" aria-label="Library backup file" required></div><p class="hint">Full backups restore original file bytes, notes, highlights, and connected items. Account tokens are never imported.</p><p class="form-error" role="alert"></p><div class="dialog-footer"><span>Everything, a little more together.</span><button type="submit" class="button primary">${icon('upload')}Import library</button></div></form>`);}

// Preserve the article selection when the highlight button receives a pointer gesture.
document.addEventListener('pointerdown',e=>{if(e.target.closest('[data-action="highlight-reader"],[data-action="format"]'))e.preventDefault();});
document.addEventListener('click',e=>{
 if(e.target.closest('.notion-editor [data-editor-action="markdown"]')){setEditorMode('markdown');return;}
 const target=e.target.closest('[data-action]');if(target){e.preventDefault();const {action,id}=target.dataset;run(async()=>{
 switch(action){
  case 'ask-ai':{const editor=getEditorContext(),space=getCurrentSpaceContext();aiUI?.open({intent:target.dataset.intent||'chat',scope:editor?'selected':space&&!selected.size?'space':undefined,spaceKey:space?.key,itemId:id||editor?.id,selection:editor?.selection,draft:editor?.draft});break;}
  case 'ask-space':{const space=getCurrentSpaceContext();if(!space)throw new Error('Choose an available space first.');aiUI?.open({intent:'chat',scope:'space',spaceKey:space.key});break;}
  case 'space-map':mapScopeKey=getCurrentSpaceContext()?.key||'';currentView='map';typeFilter='all';search='';activeTag='';selected.clear();render();break;
  case 'map-link-item':startMapLink();break;
  case 'navigate':{const view=target.dataset.view;if(view==='map'&&currentView!=='map')mapScopeKey=getCurrentSpaceContext()?.key||'';currentView=view;typeFilter='all';selected.clear();activeTag='';mobileNav=false;render();break;}
  case 'toggle-nav':mobileNav=!mobileNav;$('.workspace').classList.toggle('nav-open',mobileNav);$('.sidebar').inert=matchMedia('(max-width:620px)').matches&&!mobileNav;$('.mobile-menu').setAttribute('aria-expanded',String(mobileNav));break;
  case 'type-filter':typeFilter=target.dataset.type;renderHead();renderContent();break;
  case 'filter-tag':activeTag=target.dataset.tag;currentView='all';typeFilter='all';render();break;
  case 'clear-tag':activeTag='';renderHead();renderContent();break;
  case 'clear-search':search='';$('#search').value='';renderContent();break;
  case 'layout':{layout=target.dataset.layout;const space=getCurrentSpaceContext(),side=params.get('view')==='sidepanel';if(space?.kind==='collection'){const c=collection(space.id);await store.updateCollection(c.id,{[side?'sidebarLayout':'layout']:layout},{expectedUpdatedAt:c.updatedAt});}else await store.updateSettings({[space?.kind==='inbox'?(side?'inboxSideLayout':'inboxLayout'):(side?'sideLayout':'layout')]:layout});renderHead();renderContent();break;}
  case 'toggle-select':selectMode=!selectMode;if(!selectMode)selected.clear();renderHead();renderContent();break;
  case 'clear-selection':selected.clear();selectMode=false;renderContent();break;
  case 'new-note':addItem('note');break;
  case 'add-item':addItem();break;
  case 'add-kind':addItem(target.dataset.kind);break;
  case 'upload':$('#file-input').click();break;
  case 'new-collection':editCollection();break;
  case 'collection-menu':editCollection(id);break;
  case 'open-item':if($('#edit-form')?.dataset.dirty==='true')await saveOpenEdits();openItem(id);break;
  case 'item-menu':itemMenu(id);break;
  case 'close-modal':closeModal();break;
  case 'favorite':{const form=$('#edit-form'),editingThis=form?.dataset.id===id;const item=await store.updateItem(id,{favorite:!getItem(id).favorite},editingThis?{expectedUpdatedAt:form.dataset.revision}:{});if(editingThis&&form.isConnected)form.dataset.revision=item.updatedAt;target.classList.toggle('is-favorite',item.favorite);target.setAttribute('aria-pressed',String(item.favorite));target.setAttribute('aria-label',item.favorite?'Remove favorite':'Add to favorites');break;}
  case 'trash':await store.deleteItem(id);closeModal();toast('Moved to trash. You can restore it anytime.');break;
  case 'restore':await store.restoreItem(id);closeModal();toast('Welcome back. Item restored.');break;
  case 'permanent-delete':if(confirm('Permanently delete this item? This cannot be undone.')){const item=getItem(id);await store.permanentlyDeleteItem(id);if(item.attachmentId&&!library.items.some(i=>i.attachmentId===item.attachmentId))await store.deleteAttachment(item.attachmentId);closeModal();toast('Item permanently deleted.');}break;
  case 'archive':await store.updateItem(id,{archived:!getItem(id).archived});closeModal();toast('Library updated.');break;
  case 'pin':await store.updateItem(id,{pinned:!getItem(id).pinned});closeModal();toast('Notebook updated.');break;
  case 'move-item':chooseCollection([id]);break;
  case 'bulk-move':chooseCollection([...selected]);break;
  case 'bulk-favorite':for(const key of selected)await store.updateItem(key,{favorite:true});selected.clear();renderContent();toast('Favorites updated.');break;
  case 'bulk-trash':for(const key of selected)await store.deleteItem(key);selected.clear();renderContent();toast('Selected items moved to trash.');break;
  case 'delete-collection':if(confirm('Delete this space? Its items will stay in your library, in Inbox.')){const form=$('#collection-form');await store.deleteCollection(id,form?.dataset.id===id?{expectedUpdatedAt:form.dataset.revision}:{});if(form)form.dataset.dirty='false';currentView='inbox';closeModal();render();toast('Space deleted. Your items are safe.');}break;
  case 'toggle-notebook':notebook=!notebook;await store.updateSettings({showNotebook:notebook});render();break;
  case 'open-full':await openFullWorkspace();break;
  case 'screenshot':await showCaptureChoices();break;
  case 'capture-visible':{const result=await chromeRequest('captureScreenshot');toast('Screenshot saved with its source.');library=await store.loadLibrary();openItem(result.id);break;}
  case 'capture-full':await beginFullCapture();break;
  case 'cancel-full-capture':await cancelFullCapture();break;
  case 'view-capture':if(captureJob?.itemId){if($('#edit-form')?.dataset.dirty==='true')await saveOpenEdits();library=await store.loadLibrary();openItem(captureJob.itemId);}break;
  case 'capture':{const result=await chromeRequest('captureCurrent');toast('Current page saved to your library.');openItem(result.id);break;}
  case 'settings':showSettings();break;
  case 'help':showHelp();break;
  case 'references':showReferences();break;
  case 'integrations':await showIntegrations();break;
  case 'show-mcp':await showMcp(target.dataset.client);break;
  case 'test-raindrop':{await ensureOrigin('https://api.raindrop.io/*');const result=await integrations.testRaindropConnection();toast('Raindrop connection verified.');await showIntegrations();break;}
  case 'import-raindrop':await ensureOrigin('https://api.raindrop.io/*');target.disabled=true;target.querySelector('span').textContent='Importing…';try{const result=await integrations.importFromRaindrop({onProgress:p=>toast(typeof p==='string'?p:`Importing ${p.items||p.bookmarks||''} items…`)});toast(`Raindrop import complete. ${result.items??''} items imported.`);await showIntegrations();}finally{target.disabled=false;}break;
  case 'disconnect-raindrop':await integrations.disconnectRaindrop();toast('Raindrop disconnected. Your imported items stay here.');await showIntegrations();break;
  case 'send-raindrop':await ensureOrigin('https://api.raindrop.io/*');await integrations.sendToRaindrop(getItem(id));toast('Item sent to Raindrop.');closeModal();break;
  case 'stop-sync':stopSync?.();stopSync=null;await integrations.disconnectBridge();toast('Bridge sync stopped.');await showIntegrations();break;
  case 'import':showImport();break;
  case 'import-browser':if(!isExtension)throw new Error('Chrome bookmark import is available in the installed extension.');if(!await chrome.permissions.request({permissions:['bookmarks']}))throw new Error('Bookmark access was not granted.');{const result=await chromeRequest('importBrowserBookmarks');toast(`${result.imported} browser bookmarks imported.`);}break;
  case 'export-json':await exportBackup();break;
  case 'export-html':exportHtml();break;
  case 'export-markdown':download(exportNotesMarkdown(library),'still-notes.md','text/markdown');toast('Notes exported.');break;
  case 'download-file':{const attachment=await store.getAttachment(getItem(id).attachmentId);if(!attachment)throw new Error('Original file is unavailable on this device. Restore a full backup to recover it.');download(attachment.blob,attachment.name||getItem(id).fileName,attachment.mime);break;}
  case 'format':insertFormat(target.dataset.format);break;
  case 'editor-mode':setEditorMode(target.dataset.mode);break;
  case 'toggle-preview':setEditorMode($('.editor-preview')?.hidden?'preview':'blocks');break;
  case 'reader-size':{const reader=$('.reader-content');reader.style.fontSize=(parseInt(getComputedStyle(reader).fontSize)>=21?15:parseInt(getComputedStyle(reader).fontSize)+2)+'px';break;}
  case 'highlight-reader':{const selection=window.getSelection();if(!selection?.toString().trim()||!$('.reader-content').contains(selection.anchorNode))throw new Error('Select a passage in the saved article first.');const text=selection.toString();await saveOpenEdits();await store.updateItem(id,{highlights:[...getItem(id).highlights,{id:crypto.randomUUID(),text,color:'yellow',url:getItem(id).url}]});openItem(id);toast('Passage saved beside your notes.');break;}
  case 'add-highlight':await saveOpenEdits();openModal(`${modalHeader('Keep the words that stay.')}<form id="highlight-form" data-id="${esc(id)}"><label>Highlight<textarea name="text" rows="5" required autofocus placeholder="The part you want to come back to…"></textarea></label><div class="dialog-footer">${button('open-item','Back','back','button secondary',`data-id="${esc(id)}"`)}<button class="button primary" type="submit">${icon('highlight')}Keep highlight</button></div></form>`);break;
  case 'remove-highlight':await saveOpenEdits();await store.updateItem(id,{highlights:getItem(id).highlights.filter(h=>h.id!==target.dataset.highlight)});openItem(id);break;
  case 'link-item':await saveOpenEdits();chooseLinkTarget(id);break;
  case 'unlink-item':await saveOpenEdits();await store.updateItem(id,{relatedIds:getItem(id).relatedIds.filter(v=>v!==target.dataset.related)});{const other=getItem(target.dataset.related);if(other?.relatedIds.includes(id))await store.updateItem(other.id,{relatedIds:other.relatedIds.filter(v=>v!==id)});}openItem(id);break;
  case 'new-linked-note':{const source=getItem(id);const note=await store.saveItem({type:'note',title:`Thoughts on ${source.title}`,collectionId:source.collectionId,relatedIds:[id],content:`# Thoughts on ${source.title}\n\n`});await store.updateItem(id,{relatedIds:[...source.relatedIds,note.id]});openItem(note.id);break;}
 }
 });return;}
 const card=e.target.closest('[data-open]');if(card&&!e.target.closest('button,a,input'))openItem(card.dataset.open);
});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;renderContent();}if(e.target.closest('#edit-form,#collection-form'))e.target.closest('form').dataset.dirty='true';});
document.addEventListener('change',e=>run(async()=>{
 if(e.target.id==='sort'){sort=e.target.value;renderContent();}
 if(e.target.id==='map-space'){mapScopeKey=e.target.value;selected.clear();render();}
 if(e.target.dataset.select){e.target.checked?selected.add(e.target.dataset.select):selected.delete(e.target.dataset.select);renderContent();}
 if(e.target.dataset.taskIndex!==undefined){const form=e.target.closest('form'),area=$('#note-editor');let count=0;area.value=area.value.split('\n').map(line=>/^[-*] \[[ x]\]/i.test(line)?(count++===Number(e.target.dataset.taskIndex)?line.replace(/\[[ x]\]/i,e.target.checked?'[x]':'[ ]'):line):line).join('\n');form.dataset.dirty='true';}
 if(e.target.id==='file-input'){for(const file of e.target.files)await addFile(file);e.target.value='';toast('Files saved to your library.');}
 if(e.target.id==='import-input'){await importFile(e.target.files[0]);e.target.value='';}
}));
async function saveOpenEdits(){
 const form=$('#edit-form');if(!form)return;
 const area=$('#note-editor');if(blockEditor&&!blockEditor.root.hidden&&area)area.value=blockEditor.getMarkdown();
 const data=new FormData(form),snapshot=JSON.stringify([...data]);
 const patch={title:String(data.get('title')),content:String(data.get('content')),tags:String(data.get('tags')).split(',').map(s=>s.trim()).filter(Boolean),collectionId:String(data.get('collectionId')||''),reminderAt:data.get('reminderAt')?new Date(data.get('reminderAt')).toISOString():null};
 if(data.has('url'))patch.url=String(data.get('url'));if(data.has('excerpt'))patch.excerpt=String(data.get('excerpt'));
 const item=await store.updateItem(form.dataset.id,patch,{expectedUpdatedAt:form.dataset.revision});
 if(form.isConnected){form.dataset.revision=item.updatedAt;form.dataset.dirty=JSON.stringify([...new FormData(form)])===snapshot?'false':'true';}
 aiUI?.refreshContext?.();return item;
}
document.addEventListener('submit',e=>{if(!e.target.closest('dialog'))return;e.preventDefault();const form=e.target;run(async()=>{const submit=$('[type="submit"]',form);if(submit)submit.disabled=true;const error=$('.form-error',form);if(error)error.textContent='';try{const data=new FormData(form);
 if(form.id==='add-form'){if(data.get('type')==='file'){await addFile(data.get('attachment'),String(data.get('collectionId')||''),String(data.get('tags')||''));}else{const content=String(data.get('content')||'');await store.saveItem({type:String(data.get('type')),url:String(data.get('url')||''),title:String(data.get('title')||''),content,excerpt:data.get('type')==='note'?previewText(content):'',collectionId:String(data.get('collectionId')||''),tags:String(data.get('tags')||'').split(',').map(s=>s.trim()).filter(Boolean)});}closeModal();toast('A good find, safely kept.');}
 if(form.id==='import-form'){await importFile(data.get('libraryFile'));}
 if(form.id==='edit-form'){await saveOpenEdits();closeModal();toast('Thoughts saved. A little more connected.');}
 if(form.id==='collection-form'){const cover=String(data.get('cover')||'').trim();if(cover&&!/^(?:assets|images)\//i.test(cover)&&!/^data:image\/(?:png|jpeg|gif|webp|avif);base64,/i.test(cover))store.safeUrl(cover,{optional:false});const value={name:String(data.get('name')),description:String(data.get('description')||''),cover,pinned:data.has('pinned'),layout:String(data.get('layout')),sidebarLayout:String(data.get('sidebarLayout')),color:String(data.get('color')),icon:String(data.get('icon')),parentId:String(data.get('parentId')||'')};const saved=form.dataset.id?await store.updateCollection(form.dataset.id,value,{expectedUpdatedAt:form.dataset.revision}):await store.createCollection(value);form.dataset.dirty='false';form.dataset.revision=saved.updatedAt;closeModal();toast('Space saved. A little more organized.');}
 if(form.id==='map-link-start'){chooseLinkTarget(String(data.get('sourceId')||''));}
 if(form.id==='move-form'){for(const id of JSON.parse(form.dataset.ids))await store.updateItem(id,{collectionId:String(data.get('collectionId'))});selected.clear();closeModal();render();toast('Everything in its place.');}
 if(form.id==='highlight-form'){const item=getItem(form.dataset.id);await store.updateItem(item.id,{highlights:[...item.highlights,{id:crypto.randomUUID(),text:String(data.get('text')),color:'yellow',url:item.url,createdAt:new Date().toISOString()}]});openItem(item.id);toast('Highlight kept with its source.');}
 if(form.id==='link-form'){const item=getItem(form.dataset.id),relatedId=String(data.get('relatedId')||'');if(!getItem(relatedId))throw new Error('Choose an item to connect.');await store.updateItem(item.id,{relatedIds:[...item.relatedIds,relatedId]});const other=getItem(relatedId);await store.updateItem(relatedId,{relatedIds:[...other.relatedIds,item.id]});openItem(item.id);toast('Ideas connected.');}
 if(form.id==='settings-form'){await store.updateSettings({theme:String(data.get('theme')),compact:data.has('compact'),showNotebook:data.has('showNotebook')});notebook=data.has('showNotebook');closeModal();render();toast('A little more you.');}
 if(form.id==='raindrop-form'){await integrations.setRaindropToken(String(data.get('token')));toast('Token saved on this device. Test the connection to verify it.');await showIntegrations();}
 if(form.id==='bridge-form'){await ensureOrigin(new URL(String(data.get('url'))).hostname==='localhost'?'http://localhost/*':'http://127.0.0.1/*');stopSync?.();await integrations.configureBridge({url:String(data.get('url')),token:String(data.get('token'))});await integrations.syncBridgeOnce();beginBridgeSync();toast('Local bridge paired. Library sync is running.');await showIntegrations();}
 }catch(err){if(error)error.textContent=err.message;else throw err;}finally{if(submit)submit.disabled=false;}});});
function insertFormat(type){const area=$('#note-editor');if(!area)return;if(blockEditor&&!blockEditor.root.hidden){blockEditor.command(type);return;}setEditorMode('markdown');const start=area.selectionStart,end=area.selectionEnd,selection=area.value.slice(start,end);const replacements={bold:`**${selection||'a little emphasis'}**`,heading:`\n## ${selection||'A new thought'}\n`,task:`\n- [ ] ${selection||'Something to do'}\n`,quote:`\n> ${selection||'Words worth keeping'}\n`};area.setRangeText(replacements[type],start,end,'end');area.dispatchEvent(new Event('input',{bubbles:true}));area.focus();area.closest('form').dataset.dirty='true';}
async function addFile(file,collectionId=currentView.startsWith('collection:')?currentView.slice(11):'',tags=''){if(!file?.size&&!(file instanceof File))throw new Error('Choose a file first.');if(file.size>100*1024*1024)throw new Error('This file is over 100 MB. Try a smaller file.');let cover='';if(/^image\/(png|jpeg|gif|webp|avif)$/.test(file.type)&&file.size<5*1024*1024)cover=await imageThumbnail(file);const articleContent=/^(text\/plain|text\/markdown)$/.test(file.type)||/\.(txt|md)$/i.test(file.name)?(await file.text()).slice(0,250000):'';const metadata=await store.saveAttachment(file);try{await store.saveItem({type:file.type.startsWith('image/')?'image':file.type.startsWith('video/')?'video':'file',title:file.name,...metadata,cover,articleContent,collectionId,tags:tags.split(',').map(s=>s.trim()).filter(Boolean)});}catch(e){await store.deleteAttachment(metadata.attachmentId);throw e;}}
function beginBridgeSync(){stopSync?.();stopSync=integrations.startBridgeSync({onStatus:s=>{const el=$('#bridge-status');if(el)el.textContent=s.connected?'Connected':`Disconnected · ${s.error||'Bridge unavailable'}`;}});}
async function imageThumbnail(file){const bitmap=await createImageBitmap(file);try{const scale=Math.min(1,640/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.8);}finally{bitmap.close();}}
const blobDataUrl=blob=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('The file could not be read.'));reader.readAsDataURL(blob);});
function download(content,name,type='application/octet-stream'){const blob=content instanceof Blob?content:new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function exportBackup(){const snapshot=await createFullBackup(store);download(JSON.stringify(snapshot,null,2),`still-backup-${new Date().toISOString().slice(0,10)}.json`,'application/json');toast('Your complete library, ready to take along.');}
function exportHtml(){download(exportBookmarkHtml(library),'still-bookmarks.html','text/html');toast('Bookmarks exported as HTML.');}
async function importFile(file){if(!file)return;const result=await importPortableFile(file,store);toast(`${result.items} ${result.items===1?'item':'items'} imported. Your library is ready.`);for(const warning of result.warnings)toast(warning,true);closeModal();}
document.addEventListener('keydown',e=>{const node=e.target.closest('[data-map-node]');if(node&&['Enter',' '].includes(e.key)){e.preventDefault();run(async()=>{if($('#edit-form')?.dataset.dirty==='true')await saveOpenEdits();openItem(node.dataset.mapNode);});return;}if(e.target.closest('.type-tabs')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('.type-tab')];const index=tabs.indexOf(e.target);const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;const type=tabs[next].dataset.type;tabs[next].click();document.querySelector(`.type-tab[data-type="${type}"]`)?.focus();return;}const editing=!!e.target.closest('input,textarea,select,[contenteditable="true"]');if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#active-dialog')&&!closeModal())return;$('#search')?.focus();return;}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&$('#edit-form')){e.preventDefault();$('#edit-form').requestSubmit();return;}if(editing||$('#active-dialog')||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key.toLowerCase()==='n'){e.preventDefault();addItem('note');}if(e.key.toLowerCase()==='a'){e.preventDefault();addItem();}});
